-- ALTER DYNAMIC TABLE refresh, SET and UNSET
-- https://docs.snowflake.com/en/sql-reference/sql/alter-dynamic-table

ALTER DYNAMIC TABLE t1, t2, t3 REFRESH;

ALTER DYNAMIC TABLE IF EXISTS t1, t2 REFRESH COPY SESSION;

ALTER DYNAMIC TABLE t SET SCHEDULER = DISABLE;

ALTER DYNAMIC TABLE t SET SCHEDULER = ENABLE;

ALTER DYNAMIC TABLE t SET INITIALIZATION_WAREHOUSE = wh;

ALTER DYNAMIC TABLE t UNSET INITIALIZATION_WAREHOUSE;

ALTER DYNAMIC TABLE t SET EXECUTE AS USER my_user;

ALTER DYNAMIC TABLE t SET EXECUTE AS USER my_user USE SECONDARY ROLES NONE;

ALTER DYNAMIC TABLE t UNSET EXECUTE AS USER;

ALTER DYNAMIC TABLE t SET ROW_TIMESTAMP = TRUE;

ALTER DYNAMIC TABLE t UNSET ROW_TIMESTAMP;

ALTER DYNAMIC TABLE t SET FROZEN WHERE (ts < '2020-01-01');

ALTER DYNAMIC TABLE t UNSET FROZEN WHERE;

ALTER DYNAMIC TABLE t UNSET DCM PROJECT;

ALTER DYNAMIC TABLE t SET TARGET_LAG = '10 minutes', WAREHOUSE = wh;
